class Solution {
public:
    vector<int> maxPrimes(int n, int s) {
        if (n < 2) return {};
        vector<char> isPrime(n + 1, true);
        isPrime[0] = isPrime[1] = false;
        for (int i = 2; i * 1LL * i <= n; ++i) {
            if (isPrime[i]) {
                for (int j = i * i; j <= n; j += i)
                    isPrime[j] = false;
            }
        }

        vector<int> ans;
        long long curSum = 0;
        for (int p = 2; p <= n; ++p) {
            if (!isPrime[p]) continue;
            if (curSum + p <= s) {
                ans.push_back(p);
                curSum += p;
            } else {
                break;          // further primes are larger, will only increase the sum
            }
        }
        return ans;
    }
};

