class Solution:
    def maxPrimes(self, n: int, s: int) -> list[int]:
        if n < 2:
            return []
        is_prime = [True] * (n + 1)
        is_prime[0] = is_prime[1] = False
        i = 2
        while i * i <= n:
            if is_prime[i]:
                j = i * i
                while j <= n:
                    is_prime[j] = False
                    j += i
            i += 1

        ans = []
        cur_sum = 0
        for p in range(2, n + 1):
            if not is_prime[p]:
                continue
            if cur_sum + p <= s:
                ans.append(p)
                cur_sum += p
            else:
                break  # further primes are larger, will only increase the sum
        return ans

