/**
 * @param {number} n
 * @param {number} s
 * @return {number[]}
 */
var maxPrimes = function(n, s) {
    if (n < 2) return [];
    // Sieve of Eratosthenes
    const isPrime = new Array(n + 1).fill(true);
    isPrime[0] = isPrime[1] = false;
    for (let i = 2; i * i <= n; i++) {
        if (isPrime[i]) {
            for (let j = i * i; j <= n; j += i) {
                isPrime[j] = false;
            }
        }
    }

    const ans = [];
    let curSum = 0;
    for (let p = 2; p <= n; p++) {
        if (!isPrime[p]) continue;
        if (curSum + p <= s) {
            ans.push(p);
            curSum += p;
        } else {
            break; // further primes are larger, will only increase the sum
        }
    }
    return ans;
};
